(42, 'Paper Frame Box', 'paper-frame-box', NULL, 'Paper Edge Protector', '', '', 'product/product-1784540717-972.png', '', 'Multi-layer Kraft, Full Box Framing, Box, Frame', 'Material: Multi-layer Kraft\r\nUsage: Full Box Framing\r\nSupply Ability: 5000 / Day', 'Paper Frame Box | AMR Packwell', 'Paper Frame Box made from Multi-layer Kraft for Full Box Framing.', 'Paper Frame Box, Multi-layer Kraft, Full Box Framing, Box, Frame', 'active', 0, 8, 0, '2026-07-20 09:45:17', '2026-07-20 09:45:28'),
(43, 'Protection Edge Boards', 'protection-edge-boards', NULL, 'Paper Edge Protector', '', '', 'product/product-1784540823-369.png', '', 'Paper, Duplex Board, Box, Frame', 'Material: Paper\r\nUsage: Duplex Board\r\nSupply Ability: 1000 / Day', 'Protection Edge Boards | AMR Packwell', 'Protection Edge Boards made from Paper for Duplex Board.', 'Protection Edge Boards, Paper, Duplex Board, Box, Frame', 'active', 0, 9, 0, '2026-07-20 09:47:03', '2026-07-20 09:47:03'),
(44, 'Corrugated Boxes', 'corrugated-boxes', NULL, '', '', '<p>About Corrugated Boxes</p><p>Choose AMR Packwell\'s premium Corrugated Boxes for all-round industrial, e-commerce, and retail packaging needs. Built with high-grade kraft and corrugated board in 3 Ply, 5 Ply, and 7 Ply configurations, these boxes deliver outstanding compression strength, burst resistance up to 200 kgf/cm², and reliable protection for your products during storage and transit.</p><p>Available in A, B, C, E, and F flute types with fully customizable dimensions, our corrugated boxes are engineered for every industry — from fragile electronics and perishable food items to heavy industrial goods and pharmaceutical shipments. Custom printing in flexo, offset, and digital formats ensures your brand identity stands out on every box.</p><p>Strength, Versatility & Performance</p><p>Corrugated boxes from AMR Packwell perform reliably across warehouses, factory floors, retail shelves, and last-mile delivery networks. Their multi-ply construction offers exceptional stacking strength, while optional moisture-resistant coatings, foam inserts, and internal dividers make them suitable for the most demanding packaging applications. Whether you need die-cut mailer boxes, slotted cartons, or heavy-duty export-grade packaging, we manufacture to your exact specifications.</p><p>Eco-Friendly & Certifications</p><p>All our corrugated boxes are manufactured using recyclable, FSC-compliant kraft paper, meeting ISO quality standards. We supply to major industrial zones across India via efficient logistics, ensuring consistent quality and on-time delivery for every bulk order dispatched from our facility.</p><p>High Burst Strength</p><p>Up to 200 kgf/cm² burst resistance</p><p>100% Recyclable</p><p>Eco-friendly kraft corrugated board</p><p>Custom Dimensions</p><p>Any L×W×H made to your specification</p><p>Custom Printing</p><p>Flexo, offset & digital print options</p><p>Company Info</p><p>Company: AMR Packwell</p><p>GST No.: 09AARCA6409K1Z5</p><p>Experience: 8+ Years</p><p>Supply: PAN India</p><p></p>', 'product/product-1784541018-268.jpg', '15', 'Corrugated Box, Custom Corrugated Box, Printed Corrugated Box, 3 Ply, 5 Ply, 7 Ply, Custom Sizes, Recyclable, Custom Printing, Heavy Duty, Moisture Resistant', 'Product Type: Corrugated Box\r\nMaterial: Kraft / Corrugated Board\r\nPly Options: 3 Ply, 5 Ply, 7 Ply\r\nFlute Type: A, B, C, E & F Flute\r\nPrinting: Flexo / Offset / Digital\r\nSize: Fully Customizable\r\nBurst Strength: Up to 200 kgf/cm²\r\nColor: Brown / White / Custom\r\nFinish: Plain / Printed / Laminated\r\nAdd-ons: Inserts, Dividers, Foam Lining\r\nSupply Ability: 2,000 Pieces / Day\r\nGST No.: 09AARCA6409K1Z5\r\nStarting Price: ₹15 INR / Piece\r\nMOQ: 100 Pieces\r\nDelivery: 3 Days', 'Corrugated Boxes | AMR Packwell', 'Premium Corrugated Boxes made from Kraft / Corrugated Board with 3 Ply, 5 Ply and 7 Ply options, custom sizes and printing.', 'Corrugated Boxes, Corrugated Box, Custom Corrugated Box, Printed Corrugated Box, Kraft Board, Corrugated Board, 3 Ply, 5 Ply, 7 Ply', 'active', 1, 10, 1, '2026-07-20 09:50:18', '2026-07-22 05:29:45'),
(45, 'Plywood Pallets', 'plywood-pallets', NULL, 'Wooden Pallets', '', '<p>About Plywood Pallets</p><p>We AMR PACKWELL manufacture durable Plywood Pallets for warehousing, dispatch, internal material movement, and export packaging. These pallets are built to support regular industrial handling while maintaining deck stability and dependable load transfer.</p><p>Our plywood pallets are preferred where customers need a smooth deck surface, dimensional consistency, and custom fabrication for specific cartons, bags, machinery parts, or stacked consignments. They are easy to integrate with forklifts, pallet trucks, stretch wrapping, and warehouse racking workflows.</p><p>We provide customized pallet sizes, pallet deck patterns, heavy-duty pallet designs, and pallet solutions for transport and export across India, helping clients reduce transit damage and improve storage efficiency.</p><p>Smooth Deck Support</p><p>Plywood top decks help distribute load evenly and give cartons, bags, and packed goods a stable base for stacking and strapping.</p><p>Built For Reuse</p><p>Designed for repeated industrial handling cycles in warehouses and dispatch operations when used within recommended load conditions.</p><p>Custom Fabrication</p><p>We manufacture pallets in client-required dimensions, entry patterns, and deck layouts to match storage, movement, and shipment needs.</p><p>Superior Strength</p><p>Made for industrial stacking and handling</p><p>Reusable Design</p><p>Suitable for repeat movement cycles</p><p>Custom Sizes</p><p>Customized for your product footprint</p><p>Bulk Pricing</p><p>Value pricing for bulk industrial supply</p><p>Company Info</p><p>Company: AMR Packwell</p><p>GST No.: 09AARCA6409K1Z5</p><p>Experience: 8+ Years</p><p>Supply: PAN India</p><p></p>', 'product/product-1784541489-447.png', '500', 'Plywood, Industrial, Custom Sizes, Reusable, Export Ready, Heavy Duty, Warehouse', 'Material: Plywood\r\nProduct Type: Plywood Pallets\r\nUsage: Storage, transport and export packaging\r\nColor: Brown\r\nSize: Customized\r\nEntry Type: 2 Way / 4 Way Options\r\nLoad Bearing: Heavy duty industrial support\r\nSurface Finish: Smooth plywood top deck\r\nMoisture Resistance: Suitable for warehouse and covered transit use\r\nCustomization: Size, thickness and pallet design available\r\nApplication: Warehouse stacking, dispatch and export consignments\r\nDurability: Reusable for repeat handling cycles\r\nSupply Ability: 1,000 Per Day\r\nStarting Price: ₹500 INR / Piece\r\nMOQ: 100 Pieces\r\nDelivery: 3–7 Days\r\nGST No.: 09AARCA6409K1Z5', 'Plywood Pallets | AMR Packwell', 'Heavy-duty Plywood Pallets for storage, transport and export packaging with custom sizes, reusable design and PAN India supply.', 'Plywood Pallets, Wooden Pallets, Plywood, Export Ready, Heavy Duty, Custom Sizes, Reusable, Warehouse Pallets, Industrial Pallets', 'active', 0, 11, 0, '2026-07-20 09:58:09', '2026-07-22 05:30:04'),
(46, 'Pine Wooden Pallets', 'pine-wooden-pallets', NULL, 'Wooden Pallets', '', '<p>About Pine Wooden Pallets</p><p>We AMR PACKWELL supply sturdy Pine Wooden Pallets for regular warehouse use, internal movement, dispatch preparation, and organized stacking of finished goods.</p><p>Pine wood pallets are valued for their practical strength, workable structure, and ability to be fabricated in customized sizes. They are suitable for cartons, sacks, components, and general material handling where customers need reliable support and economical pallet supply.</p><p>We manufacture custom pine pallets, industrial wooden pallets, storage pallets, and dispatch pallets designed around customer load needs, product footprint, and handling preferences.</p><p>Strong Daily Handling</p><p>Designed for routine forklift and pallet-truck movement in storage and dispatch environments.</p><p>Practical Construction</p><p>Pine wood construction gives a balanced combination of strength, handling ease, and economical supply.</p><p>Custom Sizes</p><p>We can tailor deck size, spacing, and pallet format around your product and storage requirement.</p><p>Superior Strength</p><p>Built for routine material movement</p><p>Pine Wood Build</p><p>Natural wood pallet construction</p><p>Custom Sizes</p><p>Produced to match your load pattern</p><p>Bulk Pricing</p><p>Practical pricing for regular orders</p><p>Company Info</p><p>Company: AMR Packwell</p><p>GST No.: 09AARCA6409K1Z5</p><p>Experience: 8+ Years</p><p>Supply: PAN India</p><p></p>', 'product/product-1784541829-917.png', '50', 'Pine Wood, Custom Sizes, Reusable, Warehouse, Heavy Duty, Load Support, Bestseller', 'Material: Pine Wood\r\nProduct Type: Pine Wooden Pallets\r\nSize: Customized\r\nColor: Yellow\r\nDynamic Load: 120 Kg (Customized)\r\nLoad Capacity: 120 Kg\r\nEntry Type: 2 Way / 4 Way Options\r\nSurface Finish: Smooth wooden top deck\r\nUsage: Warehouse movement and storage\r\nCustomization: Sizes and deck patterns available\r\nDurability: Reliable for routine handling cycles\r\nMoisture Handling: Best suited for covered storage and transit\r\nSupply Ability: 100 Per Month\r\nStarting Price: ₹50 INR / Piece\r\nMOQ: 100 Pieces\r\nDelivery: 5–10 Days\r\nGST No.: 09AARCA6409K1Z5', 'Pine Wooden Pallets | AMR Packwell', 'Pine Wooden Pallets made from Pine Wood for warehouse movement and storage with custom sizes and reliable load support.', 'Pine Wooden Pallets, Wooden Pallets, Pine Wood, Custom Sizes, Warehouse, Heavy Duty, Load Support, Reusable, Industrial Pallets', 'active', 0, 12, 0, '2026-07-20 10:00:58', '2026-07-22 05:30:18'),
(47, 'Wooden Caging / Crate', 'wooden-caging-crate', NULL, 'Wooden Box/Crate', '', '<p>About Wooden Caging / Crate</p><p>We AMR PACKWELL supply sturdy Wooden Caging / Crate for regular warehouse use, internal movement, dispatch preparation, and organized stacking of finished goods.</p><p>Crate wood pallets are valued for their practical strength, workable structure, and ability to be fabricated in customized sizes. They are suitable for cartons, sacks, components, and general material handling where customers need reliable support and economical pallet supply.</p><p>We manufacture custom pine pallets, industrial wooden pallets, storage pallets, and dispatch pallets designed around customer load needs, product footprint, and handling preferences.</p><p>Strong Transit Protection</p><p>Designed for routine forklift and pallet-truck movement in storage and dispatch environments.</p><p>Built To Size</p><p>Crate wood construction gives a balanced combination of strength, handling ease, and economical supply.</p><p>Loading Friendly</p><p>We can tailor deck size, spacing, and pallet format around your product and storage requirement.</p><p>Superior Strength</p><p>Built for routine material movement</p><p>Wood Build</p><p>Natural wood pallet construction</p><p>Loading Friendly</p><p>Produced to match your load pattern</p><p>Bulk Pricing</p><p>Practical pricing for regular orders</p><p>Company Info</p><p>Company: AMR Packwell</p><p>GST No.: 09AARCA6409K1Z5</p><p>Experience: 8+ Years</p><p>Supply: PAN India</p><p></p>', 'product/product-1784541994-300.png', '200', 'Crate, Custom Sizes, Warranty, Custom Build, Heavy Duty, Load Support, Bestseller', 'Material: Wood\r\nProduct Type: Wooden Caging / Crate\r\nSize: Different Available\r\nColor: Natural Wood\r\nDynamic Load: Forklift/loading friendly (Different Available)\r\nLoad Capacity: Forklift/loading friendly\r\nEntry Type: 2 Way / 4 Way Options\r\nSurface Finish: Industrial timber construction\r\nUsage: Machine parts, fragile goods, and export cargo\r\nCustomization: Built to product dimensions\r\nDurability: Warranty available\r\nMoisture Handling: Transit-safe wooden protection\r\nSupply Ability: 100 Per Month\r\nStarting Price: ₹200 INR / Piece\r\nMOQ: 100 Pieces\r\nDelivery: 5–10 Days\r\nGST No.: 09AARCA6409K1Z5', 'Wooden Caging / Crate | AMR Packwell', 'Wooden Caging / Crate made from Wood for machine parts, fragile goods and export cargo with custom build options.', 'Wooden Caging, Wooden Crate, Crate Wood, Wooden Pallets, Custom Build, Heavy Duty, Load Support, Export Crates, Industrial Wooden Crates', 'active', 0, 13, 0, '2026-07-20 10:06:34', '2026-07-22 05:30:42'),
(48, 'Plywood Boxes', 'plywood-boxes', NULL, 'Wooden Box/Crate', '', '<p>About Plywood Boxes</p><p>We AMR PACKWELL manufacture durable Plywood Boxes for warehousing, dispatch, internal material movement, and export packaging. These boxes are built to support regular industrial handling while maintaining structural stability and dependable load protection.</p><p>Our plywood boxes are preferred where customers need strong construction, dimensional consistency, and custom fabrication for specific cartons, bags, machinery parts, or stacked consignments. They are easy to integrate with forklifts, pallet trucks, stretch wrapping, and warehouse racking workflows.</p><p>We provide customized plywood box sizes, heavy-duty box designs, and packaging solutions for transport and export across India, helping clients reduce transit damage and improve storage efficiency.</p><p>Rigid Box Protection</p><p>Pine Wood / Plywood construction helps distribute load evenly and provides a stable structure for stacking and securing packed goods.</p><p>Custom Box Build</p><p>Designed for repeated industrial handling cycles in warehouses and dispatch operations when used within recommended load conditions.</p><p>Plywood Dispatch</p><p>We manufacture boxes in client-required dimensions and designs to match storage, movement, and shipment needs.</p><p>Superior Strength</p><p>Made for industrial stacking and handling</p><p>Warranty Design</p><p>Suitable for repeat movement cycles</p><p>Custom Sizes</p><p>Different Available for your product footprint</p><p>Bulk Pricing</p><p>Value pricing for bulk industrial supply</p><p>Company Info</p><p>Company: AMR Packwell</p><p>GST No.: 09AARCA6409K1Z5</p><p>Experience: 8+ Years</p><p>Supply: PAN India</p><p></p>', 'product/product-1784542285-630.png', '100', 'Plywood, Pine Wood, Custom Sizes, Warranty, Export Ready, Heavy Duty, Packaging', 'Material: Pine Wood / Plywood\r\nProduct Type: Plywood Boxes\r\nUsage: Storage, transport and export packaging\r\nColor: Brown / Wooden\r\nSize: Different Available\r\nEntry Type: Rigid box type construction\r\nLoad Bearing: Heavy duty industrial support\r\nSurface Finish: Strong box structure\r\nMoisture Resistance: Suitable for warehouse and covered transit use\r\nCustomization: Size, thickness and pallet design available\r\nApplication: Packaging stacking, dispatch and export consignments\r\nDurability: Warranty for repeat handling cycles\r\nSupply Ability: 100 Per Month\r\nStarting Price: ₹100 INR / Piece\r\nMOQ: 100 Pieces\r\nDelivery: 3–7 Days\r\nGST No.: 09AARCA6409K1Z5', 'Plywood Boxes | AMR Packwell', 'Plywood Boxes made from Pine Wood / Plywood for storage, transport and export packaging with custom sizes and heavy-duty construction.', 'Plywood Boxes, Pine Wood, Plywood, Export Ready, Heavy Duty, Packaging, Custom Sizes, Industrial Packaging Boxes, Wooden Packaging Boxes', 'active', 0, 14, 0, '2026-07-20 10:11:25', '2026-07-22 05:30:50'),
(49, 'Eucalyptus Wooden Box', 'eucalyptus-wooden-box', NULL, 'Wooden Box/Crate', '', '<p>About Glossy Wooden Box</p><p>We AMR PACKWELL supply sturdy Eucalyptus Wooden Box for regular warehouse use, internal movement, dispatch preparation, and organized stacking of finished goods.</p><p>Glossy wood pallets are valued for their practical strength, workable structure, and ability to be fabricated in customized sizes. They are suitable for cartons, sacks, components, and general material handling where customers need reliable support and economical pallet supply.</p><p>We manufacture custom pine pallets, industrial wooden pallets, storage pallets, and dispatch pallets designed around customer load needs, product footprint, and handling preferences.</p><p>Finished Wooden Protection</p><p>Designed for routine forklift and pallet-truck movement in storage and dispatch environments.</p><p>Premium Finish</p><p>Glossy wood construction gives a balanced combination of strength, handling ease, and economical supply.</p><p>Different Sizes</p><p>We can tailor deck size, spacing, and pallet format around your product and storage requirement.</p><p>Superior Strength</p><p>Built for routine material movement</p><p>Glossy Wood / Eucalyptus Wood Build</p><p>Natural wood pallet construction</p><p>Different Sizes</p><p>Produced to match your load pattern</p><p>Bulk Pricing</p><p>Practical pricing for regular orders</p><p>Company Info</p><p>Company: AMR Packwell</p><p>GST No.: 09AARCA6409K1Z5</p><p>Experience: 8+ Years</p><p>Supply: PAN India</p><p></p>', 'product/product-1784542555-818.png', '200', 'Glossy, Custom Sizes, Emboss, Premium, Heavy Duty, Load Support, Bestseller', 'Material: Glossy Wood / Eucalyptus Wood\r\nProduct Type: Eucalyptus Wooden Box\r\nSize: Different Sizes Available\r\nColor: Glossy Lamination\r\nDynamic Load: Premium wooden box presentation (Different Sizes Available)\r\nLoad Capacity: Premium wooden box presentation\r\nEntry Type: Rigid box structure\r\nSurface Finish: Wooden box build with finished surface\r\nUsage: Premium packaging and industrial dispatch\r\nCustomization: Different sizes available\r\nDurability: Glossy finish appearance\r\nMoisture Handling: Suitable for safe handling and dispatch\r\nSupply Ability: 100 Per Month\r\nStarting Price: ₹200 INR / Piece\r\nMOQ: 100 Pieces\r\nDelivery: 5–10 Days\r\nGST No.: 09AARCA6409K1Z5', 'Eucalyptus Wooden Box | AMR Packwell', 'Eucalyptus Wooden Box made from Glossy Wood / Eucalyptus Wood for premium packaging and industrial dispatch with custom sizes.', 'Eucalyptus Wooden Box, Glossy Wood, Eucalyptus Wood, Premium Packaging, Custom Sizes, Heavy Duty, Emboss, Wooden Packaging Box, Industrial Wooden Box', 'active', 0, 15, 0, '2026-07-20 10:15:27', '2026-07-22 05:30:58'),
(50, 'Cardboard Tray', 'cardboard-tray', NULL, '', '', '<p>About Cardboard Tray</p><p>We AMR PACKWELL are a trusted manufacturer and supplier of premium Cardboard Trays and Paper Trays designed to meet the diverse packaging needs of industries across India. Our trays are manufactured using high-quality corrugated cardboard that offers excellent rigidity, durability, and protection for a wide variety of products.</p><p>Our Cardboard Trays are engineered with precision to provide secure containment and easy handling during storage, transit, and display. Available in 3-ply, 5-ply, and 7-ply construction, these trays deliver the right balance of strength and weight for every application — from food packaging to industrial parts.</p><p>We offer complete customization including custom dimensions, printing, die-cutting, and colour options. Whether you need a simple brown kraft tray or a fully printed white display tray, our manufacturing capabilities cover every requirement with fast turnaround and competitive bulk pricing.</p><p>Superior Rigidity</p><p>Multi-ply corrugated construction</p><p>100% Recyclable</p><p>Eco-friendly cardboard material</p><p>Custom Sizes</p><p>Tailored to your exact dimensions</p><p>Bulk Pricing</p><p>Competitive rates for large orders</p><p>Company Info</p><p>Company: AMR Packwell</p><p>GST No.: 09AARCA6409K1Z5</p><p>Experience: 8+ Years</p><p>Supply: PAN India</p><p></p>', 'product/product-1784542729-292.jpg', '50', 'Eco Friendly, Custom Sizes, Recyclable, Corrugated, Lightweight, Bulk Orders', 'Product Type: Cardboard Tray / Paper Tray\r\nMaterial: Corrugated Cardboard\r\nShape: Open Top Tray\r\nColor: Brown / White / Custom\r\nSize: Fully Customizable\r\nThickness: 3-ply / 5-ply / 7-ply\r\nSupply Ability: 1,000 Pieces / Day\r\nDelivery Time: 2 Days\r\nStarting Price: ₹50 INR / Piece\r\nMOQ: 100 Pieces\r\nGST No.: 09AARCA6409K1Z5', 'Cardboard Tray | AMR Packwell', 'Premium Cardboard Trays made from Corrugated Cardboard with custom sizes, recyclable material and bulk supply across India.', 'Cardboard Tray, Paper Tray, Corrugated Cardboard, Eco Friendly, Recyclable, Custom Sizes, Lightweight, Bulk Orders, Packaging Tray', 'active', 1, 16, 4, '2026-07-20 10:18:49', '2026-07-22 05:31:16'),
(51, 'Paper Angle Board Corner', 'paper-angle-board-corner', NULL, 'Paper Angle Board', '', '', 'product/product-1784542975-228.png', '13', 'Corner, Warranty, Craft Paper, LDPE', 'Paper Type: Craft Paper\r\nMaterial: LDPE\r\nHardness: Soft\r\nSize: Different Available\r\nWarranty: Yes\r\nSupply Ability: 5,000 / Day\r\nPrice: ₹13 INR / Piece', 'Paper Angle Board Corner | AMR Packwell', 'Paper Angle Board Corner made from Craft Paper and LDPE.', 'Paper Angle Board Corner, Craft Paper, LDPE, Corner, Warranty', 'active', 0, 17, 0, '2026-07-20 10:22:55', '2026-07-22 05:31:59'),
